package domain.ability.event;
public final class EnvironmentalTickEvent implements MasteryEvent { private final double realSeconds; private boolean coldBuildUpActive; private double staminaCost; private double hungerDurationMultiplier=1.0; private double thirstDurationMultiplier=1.0; public EnvironmentalTickEvent(double realSeconds,boolean coldBuildUpActive){this.realSeconds=realSeconds;this.coldBuildUpActive=coldBuildUpActive;} public double realSeconds(){return realSeconds;} public boolean coldBuildUpActive(){return coldBuildUpActive;} public void suppressColdBuildUp(){coldBuildUpActive=false;} public double staminaCost(){return staminaCost;} public void addStaminaCost(double value){staminaCost+=Math.max(0,value);} public double hungerDurationMultiplier(){return hungerDurationMultiplier;} public double thirstDurationMultiplier(){return thirstDurationMultiplier;} public void doubleSatisfiedDurations(){hungerDurationMultiplier=2;thirstDurationMultiplier=2;} }
